-- 0027: Add Vibe Coding skills while preserving the live D1 skill entries.
UPDATE sections SET zh = '{"manufacturing":["CNC 銑床","Mastercam","3D 列印","金屬焊接","雷射切割","基礎機械加工","Autodesk Inventor","AutoCAD","Fusion 360"],"programming":["C / C++ (STM32 / Cortex-M)","QMK / ChibiOS HAL","UART（實戰偵錯；I2C/SPI 學習中）","Python","Arduino / ESP32","LabVIEW"],"eda":["Altium Designer","EasyEDA Pro (立創EDA)","KiCAD","OrCAD"],"data_analysis":["TensorFlow / Keras","LSTM · Time-Series","Feature Engineering","Signal Processing","SHAP / XAI"],"vibecoding":["LLM 協作開發","需求拆解與垂直切片","前後端整合","迭代除錯與瀏覽器驗證","部署與資料同步"]}', en = '{"manufacturing":["CNC Milling","Mastercam","3D Printing","Metal Welding","Laser Cutting","Basic Machining","Autodesk Inventor","AutoCAD","Fusion 360"],"programming":["C / C++ (STM32 / Cortex-M)","QMK / ChibiOS HAL","Protocols (Experienced: UART debugging; Expanding: I2C/SPI)","Python","Arduino / ESP32","LabVIEW"],"eda":["Altium Designer","EasyEDA Pro (LCEDA)","KiCAD","OrCAD"],"data_analysis":["TensorFlow / Keras","LSTM · Time-Series","Feature Engineering","Signal Processing","SHAP / XAI"],"vibecoding":["LLM-assisted coding","Requirement slicing","Full-stack integration","Iterative debugging & browser review","Deployment & data sync"]}', updated_at = datetime('now') WHERE key = 'skills_matrix';
UPDATE sections SET zh = '{"data_analysis":{"title":"數據分析","en":"Data Analysis","overview":"主要做生醫訊號跟臨床數據，從清資料、做特徵到訓練模型、看結果，整個流程都自己跑過。","skills":[{"name":"深度學習","level":"進階","desc":"玩過 LSTM、CNN 這類時序模型，前處理到調超參數都自己來，主要拿來做生醫訊號的序列預測。","projects":["VAP 深度學習預測系統"]},{"name":"LightGBM","level":"進階","desc":"用於 BitOGuard 的不平衡二元分類，與 XGBoost 以 0.6/0.4 加權混合，搭配 SHAP 檢視每個特徵對帳戶風險分數的貢獻，並比較不同決策閾值下的 Precision 與 Recall。","projects":["AWS x BitoPro 黑客松"]},{"name":"XGBoost","level":"熟悉","desc":"在 BitOGuard 與 LightGBM 以 0.4 權重加權混合（單獨 OOF AUC 0.827）；另用在 DSP／訊號分類課程與實驗。","projects":["AWS x BitoPro 黑客松"]},{"name":"特徵工程","level":"進階","desc":"抓時域（均值、峰值）跟頻域（FFT 功率譜）特徵；電子病歷的部分用時序聚合跟 One-Hot 編碼處理，這些醫療數據缺失率都不低。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"訊號過濾","level":"熟悉","desc":"帶通濾波、Z-score 標準化、缺失值補值，把生理訊號的輸入品質顧好，模型才不會對雜訊太敏感。","projects":["VAP 深度學習預測系統"]},{"name":"數據結構化","level":"熟悉","desc":"電子病歷的 ETL 清洗、用 AWS Glue 做圖形化多跳分析，把原始的非結構化資料整理成可以丟進模型訓練的特徵矩陣。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]}]},"programming":{"title":"程式開發","en":"Programming","overview":"從嵌入式韌體寫到 ML 管線都碰過，硬體這邊用 C/C++，資料跟模型那邊用 Python。","skills":[{"name":"C / C++","level":"進階","desc":"寫嵌入式韌體最常用的語言。GPIO 控制、中斷處理、記憶體管理都算熟，ChibiOS HAL 的設定（chconf / halconf / mcuconf）跟 QMK Firmware 架構也碰過，在資源有限的 STM32 上寫底層驅動沒問題。","projects":["FRC Swerve Drive 全向輪控制系統","QMK x STM32 客製鍵盤"]},{"name":"Python","level":"進階","desc":"考過 ITS Python 國際認證。平常拿來寫 ML 管線（PyTorch、scikit-learn、pandas）、畫圖（Matplotlib），也用 AWS SDK 接雲端服務。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"LabVIEW","level":"熟悉","desc":"用圖形化介面寫過向量合成運動學演算法跟 PID 閉迴路控制，裝在競賽機器人上即時跑，那年拿到 2022 FRC 控制創新獎。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Arduino","level":"熟悉","desc":"拿來做快速原型，接過 ESP32 無線通訊、讀感測器、控制繼電器，方便在短時間內把硬體功能跑起來驗證。","projects":["ESP32 無線打地鼠機"]},{"name":"MATLAB","level":"基礎","desc":"拿來做訊號處理分析跟演算法驗證，寫程式前先用它把濾波效果、模型邏輯畫出來確認一遍。","projects":[]}]},"eda":{"title":"電路設計","en":"Electronic Design Automation","overview":"電路圖到 PCB Layout 都自己做，用過 Altium、EasyEDA Pro、KiCAD，電源管理跟 MCU 外圍電路比較熟。","skills":[{"name":"Altium Designer","level":"進階","desc":"做多層 PCB 設計的主力工具。電源規劃、阻抗匹配、DFM（可製造性設計）原則都會考慮，原理圖到 Gerber 輸出整個流程自己一個人就能搞定。","projects":["QMK x STM32 客製鍵盤"]},{"name":"EasyEDA Pro（立創EDA）","level":"熟悉","desc":"雲端版 EDA 工具，直接接立創商城的元件庫，封裝拿來就能用，打樣也能一鍵下單。QMK 數字鍵盤的 PCB 就是用它畫的，原理圖、Layout、Gerber 匯出都包了。","projects":["QMK x STM32 數字鍵盤"]},{"name":"KiCAD","level":"熟悉","desc":"開源 EDA 工具，個人專案想快速出板就會用它，元件庫管理跟 3D 封裝預覽都用得上手，概念驗證階段很方便。","projects":[]},{"name":"OrCAD","level":"基礎","desc":"畫電路圖、跑基本的 SPICE 模擬，拿來確認被動元件選型跟電源電路的行為對不對。","projects":[]}]},"manufacturing":{"title":"機構加工","en":"Manufacturing","overview":"設計到實體都做過：CNC 銑床、3D 列印、金屬焊接、雷射切割，建模用 Inventor，刀具路徑用 Mastercam。","skills":[{"name":"CNC 銑床","level":"基礎","desc":"用 CNC 銑床做鋁合金精密加工，刀具路徑規劃跟夾具設計都會自己弄，比手工銑床穩定很多，精度跟重現性都好控制。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Mastercam","level":"基礎","desc":"CNC 加工的 CAM 軟體，把 3D 模型丟進去規劃刀具路徑（鑽孔、深孔啄鑽、2D/3D 挖槽、輪廓銑削、動態銑削、倒角），模擬沒問題再輸出 NC 程式。Swerve Drive 的全向輪鋁板跟傳動心軸就是這樣加工出來的。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"3D 列印","level":"進階","desc":"FDM 快速成型，拿來驗證機構會不會干涉，或是做一些不承重的客製零件，重量跟加工成本都能壓下來，又不影響結構強度。","projects":["FRC Swerve Drive 全向輪控制系統","ESP32 無線打地鼠機"]},{"name":"Autodesk Inventor","level":"進階","desc":"做 3D 機構建模的主力工具，組件干涉分析跟動態模擬都會跑，在實際組裝前先把零件碰撞跟公差問題抓出來。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"AutoCAD","level":"進階","desc":"畫 2D 工程圖、輸出加工圖面，把尺寸標註跟公差規格標清楚，讓 CNC 操作員或外包廠商照著做就對了。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Fusion 360","level":"熟悉","desc":"快速建概念模型，CAM 整合也在裡面，初期設計想法用它試很方便，直接從 3D 模型生成加工路徑，小批量自己做。","projects":[]},{"name":"金屬焊接","level":"基礎","desc":"MIG / TIG 基礎焊接，用在 FRC 機器人底盤的鋼管結構上，焊道均不均勻、結構夠不夠強都要顧。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"雷射切割","level":"進階","desc":"板金跟壓克力結構件的精密裁切，照著 CAD 圖面就能快速做出自訂尺寸的薄板結構跟標示面板。","projects":[]},{"name":"基礎機械加工","level":"熟悉","desc":"手工銑床、車床的基本操作，量具怎麼用、工件怎麼夾都會，這些底子讓我後來學 CNC 進階加工上手得快一點。","projects":[]}]},"vibecoding":{"title":"Vibe Coding 設計","en":"Vibe Coding & Product Delivery","overview":"把需求拆成能執行、能驗證的小步驟，與 LLM 協作完成介面、資料流程、整合和部署；再回到實際執行環境檢查結果。","skills":[{"name":"LLM 協作開發","level":"熟悉","desc":"先描述目標、限制和完成條件，再用 LLM 協助產生或修改程式；把生成結果放回專案脈絡檢查，而不是直接照單全收。曾用於 FRC 團隊韌體除錯與個人網站、工具專案。","projects":["FRC 7645 — 官網與後台 CMS","Job Radar — 個人化求職雷達"]},{"name":"需求拆解與垂直切片","level":"熟悉","desc":"把使用流程拆成介面、資料欄位、API 與儲存等可逐段完成的工作；先讓主要路徑跑通，再補管理、篩選和錯誤處理。","projects":["南港高工校園樹木量測 PWA","Job Radar — 個人化求職雷達","TeamMatch — 黑客松找隊友平台"]},{"name":"前後端與服務整合","level":"熟悉","desc":"依專案選擇合適組合，串接 React／Vite、Next.js 或 Flask 介面與 Cloudflare Pages、D1、Firebase、Google Apps Script 等服務；資料與帳號設定不足時先確認邊界，不假裝功能已驗證。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","TeamMatch — 黑客松找隊友平台","Analog IC Studio — 類比 IC 自動調參平台"]},{"name":"迭代除錯與瀏覽器驗證","level":"熟悉","desc":"以錯誤訊息、網路請求和實際頁面定位問題；每次修改後啟動專案、重走主要操作，確認輸出與資料流。UI 截圖用來核對畫面，不當成功能測試的替代品。","projects":["Analog IC Studio — 類比 IC 自動調參平台","Virtual Office — 桌面像素辦公室","南港高工校園樹木量測 PWA"]},{"name":"自動化部署與資料同步","level":"熟悉","desc":"用 Git 管理修改，透過 GitHub Actions 或 Cloudflare Pages 發佈；需要時同步 D1、Google Sheets 等資料來源，並在正式網址核對頁面和資源。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","FRC 7645 — 官網與後台 CMS"]}]}}', en = '{"data_analysis":{"title":"Data Analysis","en":"Data Analysis","overview":"Mostly working with biomedical signals and clinical data — I go through the whole loop myself, from cleaning raw data and building features to training models and checking the results.","skills":[{"name":"Deep Learning","level":"進階","desc":"I''ve worked with LSTM and CNN time-series models — preprocessing, hyperparameter tuning, all of it — mainly for predicting biomedical signal sequences.","projects":["ICU VAP Early-Warning System"]},{"name":"LightGBM","level":"進階","desc":"Used in BitOGuard for imbalanced binary classification, blended 0.6/0.4 with XGBoost, with SHAP to inspect each feature''s contribution to account-risk scores and threshold comparisons for precision and recall.","projects":["AWS × BitoPro Hackathon"]},{"name":"XGBoost","level":"熟悉","desc":"Blended with LightGBM at 0.4 weight in BitOGuard (alone: OOF AUC 0.827); also used in DSP and signal-classification coursework.","projects":["AWS × BitoPro Hackathon"]},{"name":"Feature Engineering","level":"進階","desc":"Pulled out time-domain (mean, peak) and frequency-domain (FFT power spectrum) features, and handled EHR data — time-series aggregation, one-hot encoding, plenty of missing values to deal with.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"Signal Filtering","level":"熟悉","desc":"Band-pass filtering, Z-score normalization, missing-value imputation — basically cleaning up physiological signals so the model isn''t thrown off by noise.","projects":["ICU VAP Early-Warning System"]},{"name":"Data Structuring","level":"熟悉","desc":"EHR ETL cleaning and AWS Glue graph-based multi-hop analysis — turning messy unstructured data into feature matrices the model can actually train on.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]}]},"programming":{"title":"Programming","en":"Programming","overview":"I''ve touched everything from embedded firmware to ML pipelines — C/C++ for the hardware side, Python for data and models.","skills":[{"name":"C / C++","level":"進階","desc":"My go-to language for embedded firmware. Comfortable with GPIO control, interrupt handling, and memory management; also worked with ChibiOS HAL config (chconf/halconf/mcuconf) and the QMK firmware codebase on resource-constrained STM32 boards.","projects":["FRC Swerve Drive Research","QMK × STM32 Custom Numpad"]},{"name":"Python","level":"進階","desc":"Hold the ITS Python international certification. Use it daily for ML pipelines (PyTorch, scikit-learn, pandas), plotting (Matplotlib), and wiring up AWS services with the SDK.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"LabVIEW","level":"熟悉","desc":"Used graphical programming to build vector-composition kinematics and PID closed-loop control, running live on a competition robot — that project won the 2022 FRC Innovation in Control Award.","projects":["FRC Swerve Drive Research"]},{"name":"Arduino","level":"熟悉","desc":"My go-to for quick prototypes — wired up ESP32 wireless, sensor readings, and relay control to validate hardware ideas fast.","projects":["Wireless Whack-a-Mole"]},{"name":"MATLAB","level":"基礎","desc":"Used for signal processing analysis and quick algorithm checks — plotting things out to sanity-check filter behavior and model logic before writing the real implementation.","projects":[]}]},"eda":{"title":"Electronic Design","en":"Electronic Design Automation","overview":"I''ve done the full flow from schematic to PCB layout with Altium, EasyEDA Pro, and KiCAD — most comfortable with power management and MCU peripheral circuits.","skills":[{"name":"Altium Designer","level":"進階","desc":"My main tool for multi-layer PCB design — power planning, impedance matching, DFM principles, all the way from schematic to Gerber output, on my own.","projects":["QMK × STM32 Custom Numpad"]},{"name":"EasyEDA Pro (LCEDA)","level":"熟悉","desc":"A browser-based EDA tool hooked into the LCSC parts library — footprints are ready to use and you can order a prototype in one click. Used it for the QMK numpad PCB, from schematic to layout to Gerber export.","projects":["QMK × STM32 Custom Numpad"]},{"name":"KiCAD","level":"熟悉","desc":"Open-source EDA I reach for on personal projects when I need a board fast — comfortable with library management and 3D footprint preview, good for early-stage concept checks.","projects":[]},{"name":"OrCAD","level":"基礎","desc":"Basic schematic drawing and SPICE simulation — used it to check passive component choices and power circuit behavior.","projects":[]}]},"manufacturing":{"title":"Manufacturing","en":"Manufacturing","overview":"From design to physical parts — CNC milling, 3D printing, metal welding, laser cutting. Modeling in Inventor, toolpaths in Mastercam.","skills":[{"name":"CNC Milling","level":"基礎","desc":"Precision aluminum machining on CNC mills — I plan toolpaths and design fixtures myself, and it''s noticeably more accurate and repeatable than manual milling.","projects":["FRC Swerve Drive Research"]},{"name":"Mastercam","level":"基礎","desc":"CAM software for CNC — import a 3D model, plan toolpaths (drilling, 2D/3D pocketing, contour milling, dynamic milling, chamfering), simulate it, then output the NC program. Used it for the Swerve Drive''s aluminum wheel plates and drive shafts.","projects":["FRC Swerve Drive Research"]},{"name":"3D Printing","level":"進階","desc":"FDM printing for checking mechanical interference and making custom non-structural parts — cuts weight and machining cost without touching structural integrity.","projects":["FRC Swerve Drive Research","Wireless Whack-a-Mole"]},{"name":"Autodesk Inventor","level":"進階","desc":"My main tool for 3D mechanism modeling — assembly interference checks and dynamic simulation to catch part collisions and tolerance issues before anything gets built.","projects":["FRC Swerve Drive Research"]},{"name":"AutoCAD","level":"進階","desc":"2D engineering drawings for machining — dimensions and tolerances spelled out clearly enough for CNC operators or outside vendors to just follow.","projects":["FRC Swerve Drive Research"]},{"name":"Fusion 360","level":"熟悉","desc":"Quick concept modeling with built-in CAM — good for early design exploration, and you can go straight from the 3D model to a machining path for small-batch parts.","projects":[]},{"name":"Metal Welding","level":"基礎","desc":"Basic MIG/TIG welding for the FRC robot''s steel tube chassis — paying attention to bead uniformity and structural strength.","projects":["FRC Swerve Drive Research"]},{"name":"Laser Cutting","level":"進階","desc":"Precision cutting of sheet metal and acrylic from CAD drawings — a quick way to make custom thin-plate parts and label panels.","projects":[]},{"name":"Basic Machining","level":"熟悉","desc":"Manual mill and lathe basics — measuring tools, workpiece clamping — the groundwork that made picking up advanced CNC machining easier.","projects":[]}]},"vibecoding":{"title":"Vibe Coding & Product Delivery","en":"Vibe Coding & Product Delivery","overview":"Turn a request into small, runnable steps; work with an LLM on the interface, data flow, integrations, and deployment, then check the result in the running project.","skills":[{"name":"LLM-assisted coding","level":"熟悉","desc":"Describe the goal, constraints, and acceptance conditions first, then use an LLM to draft or revise code. Review the result in the project context instead of accepting generated code blindly. Used for FRC firmware debugging and personal web/tool projects.","projects":["FRC 7645 — Website & Admin CMS","Job Radar: Personalized Job Search Dashboard"]},{"name":"Requirement slicing","level":"熟悉","desc":"Break a workflow into interface, data fields, API, and storage tasks that can be built and checked one at a time. Get the main path running before adding admin, filters, and error handling.","projects":["NKHS Campus Tree Measurement PWA","Job Radar: Personalized Job Search Dashboard","TeamMatch — Hackathon Teammate Finder"]},{"name":"Full-stack integration","level":"熟悉","desc":"Choose a fitting stack and connect React/Vite, Next.js, or Flask interfaces with services such as Cloudflare Pages, D1, Firebase, and Google Apps Script. Check configuration and access boundaries instead of claiming an unverified integration works.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","TeamMatch — Hackathon Teammate Finder","Analog IC Studio — Automated Analog IC Tuning Platform"]},{"name":"Iterative debugging & browser review","level":"熟悉","desc":"Use error messages, network requests, and the running page to locate issues. After each change, launch the project and walk through its main flow. Use screenshots to review presentation, not as a substitute for functional tests.","projects":["Analog IC Studio — Automated Analog IC Tuning Platform","Virtual Office — Desktop Pixel Workspace","NKHS Campus Tree Measurement PWA"]},{"name":"Deployment & data sync","level":"熟悉","desc":"Track changes with Git, publish through GitHub Actions or Cloudflare Pages, sync sources such as D1 or Google Sheets when needed, and verify the production URL and assets.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","FRC 7645 — Website & Admin CMS"]}]}}', updated_at = datetime('now') WHERE key = 'skills_detail';
